    "accesibilidad": {
      "alt": "Clasificación del estado de shock",
      "descripcion": "En el centro superior, la figura del lecho capilar representa el destino común de todos los tipos de shock: el tejido no recibe oxígeno. Debajo, cuatro columnas presentan los cuatro tipos con la figura de su mecanismo. Hipovolémico: falta volumen, por hemorragia interna o externa, quemaduras extensas, vómito y diarrea o tercer espacio; el fallo está en la precarga. Cardiogénico: la bomba falla, por infarto extenso, arritmias graves, miocardiopatías o valvulopatía aguda; el fallo está en la contractilidad. Distributivo: el continente se dilata, en el shock séptico, anafiláctico y neurogénico; el fallo está en la resistencia vascular. Obstructivo: algo obstruye, por neumotórax a tensión, taponamiento cardíaco o tromboembolia pulmonar; el llenado o la salida están bloqueados."
    },
