    "accesibilidad": {
      "alt": "Curva de disociación de la oxihemoglobina",
      "descripcion": "Gráfica con la presión parcial de oxígeno en el eje horizontal, de 0 a 100 milímetros de mercurio, y la saturación de la hemoglobina en el eje vertical, de 0 a 100 por ciento. La curva tiene forma de S: sube muy poco entre 0 y 20 milímetros de mercurio, sube con rapidez entre 20 y 60, y se aplana por encima de 60, donde la saturación ya supera el 90 por ciento. El punto P50 está en torno a 26,6 milímetros de mercurio con saturación del 50 por ciento. Dos fichas explican el desplazamiento a la derecha, que suelta más oxígeno al tejido con aumento de dióxido de carbono, de temperatura y de 2,3-DPG y descenso del pH, y el desplazamiento a la izquierda, que retiene el oxígeno en las condiciones opuestas."
    },
