      "descripcion": "Una fórmula central establece que el gasto cardíaco es igual a la frecuencia cardíaca multiplicada por el volumen sistólico. Debajo, dos fichas definen cada factor: la frecuencia como latidos por minuto y el volumen sistólico como mililitros expulsados en cada latido. Más abajo, tres fichas descomponen el volumen sistólico en precarga, contractilidad y poscarga. La figura del corazón acompaña la fórmula y una nota final explica cómo se traduce cada determinante en la valoración prehospitalaria."
